package com.bank.trade;

import java.util.logging.Logger;

public class SingleTradeProfitFinder {

    private static final Logger log = Logger.getLogger(SingleTradeProfitFinder.class.getName());

    public int maxProfit(int[] prices) {
        if (prices.length == 0) return 0;
        int minPrice = prices[0];                      // cheapest buy so far
        int maxProfit = 0;                             // default: no profitable trade
        for (int p : prices) {
            if (p < minPrice) minPrice = p;            // better buy day
            else maxProfit = Math.max(maxProfit, p - minPrice); // sell today
        }
        final int best = maxProfit;
        log.info(() -> "Max single-trade profit = " + best);
        return maxProfit;
    }
}
