package com.bank.trade;

import java.util.logging.ConsoleHandler;
import java.util.logging.Logger;

public class BuySellDemo {

    private static final Logger log = Logger.getLogger(BuySellDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
    }

    public static void main(String[] args) {
        log.info("National Bank of India — Single-Trade Profit Finder (Buy/Sell Stock)");
        int[] prices = {7, 1, 5, 3, 6, 4};
        SingleTradeProfitFinder finder = new SingleTradeProfitFinder();
        log.info("Best = " + finder.maxProfit(prices)); // 5 (buy 1, sell 6)
    }
}
